-- 0004_schools_import (BE-05 step 1): schools extension, jpns, ppds, import_jobs, users search indexes.
-- Generated by Prisma (migrate diff), then edited by hand: identity columns (GENERATED ALWAYS), CHECK
-- constraints (enums are text + check), functional indexes for the list searches. Plan 14.2, data model 3.1/3.2.
-- users already carries every column the card lists (BE-03 created the full set, data model 3.1).

-- AlterTable
ALTER TABLE "schools" ADD COLUMN     "city" TEXT,
ADD COLUMN     "join_code" TEXT,
ADD COLUMN     "jpn_id" BIGINT,
ADD COLUMN     "ppd_id" BIGINT,
ADD COLUMN     "type" TEXT;

-- CreateTable
CREATE TABLE "import_jobs" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "kind" TEXT NOT NULL,
    "mode" TEXT NOT NULL,
    "created_by_id" BIGINT,
    "school_id" BIGINT,
    "total_rows" INTEGER NOT NULL DEFAULT 0,
    "imported_count" INTEGER NOT NULL DEFAULT 0,
    "failed_count" INTEGER NOT NULL DEFAULT 0,
    "failures" JSONB NOT NULL DEFAULT '[]',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "import_jobs_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "jpns" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "legacy_source" TEXT,
    "legacy_id" TEXT,

    CONSTRAINT "jpns_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ppds" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "jpn_id" BIGINT NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "legacy_source" TEXT,
    "legacy_id" TEXT,

    CONSTRAINT "ppds_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ix_import_jobs_created_by_id_created_at" ON "import_jobs"("created_by_id", "created_at");

-- CreateIndex
CREATE INDEX "ix_import_jobs_school_id" ON "import_jobs"("school_id");

-- CreateIndex
CREATE UNIQUE INDEX "uq_jpns_code" ON "jpns"("code");

-- CreateIndex
CREATE UNIQUE INDEX "uq_jpns_legacy" ON "jpns"("legacy_source", "legacy_id");

-- CreateIndex
CREATE UNIQUE INDEX "uq_ppds_code" ON "ppds"("code");

-- CreateIndex
CREATE INDEX "ix_ppds_jpn_id" ON "ppds"("jpn_id");

-- CreateIndex
CREATE UNIQUE INDEX "uq_ppds_legacy" ON "ppds"("legacy_source", "legacy_id");

-- CreateIndex
CREATE UNIQUE INDEX "uq_schools_join_code" ON "schools"("join_code");

-- CreateIndex
CREATE INDEX "ix_schools_state_district" ON "schools"("state", "district");

-- CreateIndex
CREATE INDEX "ix_schools_ppd_id" ON "schools"("ppd_id");

-- CreateIndex
CREATE INDEX "ix_schools_jpn_id" ON "schools"("jpn_id");

-- AddForeignKey
ALTER TABLE "import_jobs" ADD CONSTRAINT "fk_import_jobs_created_by_id" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "import_jobs" ADD CONSTRAINT "fk_import_jobs_school_id" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ppds" ADD CONSTRAINT "fk_ppds_jpn_id" FOREIGN KEY ("jpn_id") REFERENCES "jpns"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "schools" ADD CONSTRAINT "fk_schools_jpn_id" FOREIGN KEY ("jpn_id") REFERENCES "jpns"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "schools" ADD CONSTRAINT "fk_schools_ppd_id" FOREIGN KEY ("ppd_id") REFERENCES "ppds"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- Row convention checks (plan 14.2) on the new migratable tables.
ALTER TABLE "jpns" ADD CONSTRAINT "ck_jpns_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "ppds" ADD CONSTRAINT "ck_ppds_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));

-- Enums as text + check (English codes; SCHOOL_TYPES of @pp/contract, data model E-school_type / E-import_*).
ALTER TABLE "schools" ADD CONSTRAINT "ck_schools_type" CHECK ("type" IS NULL OR "type" IN ('SK', 'SMK', 'SJK(C)', 'SJK(T)', 'MRSM', 'SBP'));
ALTER TABLE "import_jobs" ADD CONSTRAINT "ck_import_jobs_kind" CHECK ("kind" IN ('users', 'students'));
ALTER TABLE "import_jobs" ADD CONSTRAINT "ck_import_jobs_mode" CHECK ("mode" IN ('paste', 'csv'));
ALTER TABLE "import_jobs" ADD CONSTRAINT "ck_import_jobs_counts" CHECK (
  "total_rows" >= 0 AND "imported_count" >= 0 AND "failed_count" >= 0
);
ALTER TABLE "import_jobs" ADD CONSTRAINT "ck_import_jobs_failures" CHECK (jsonb_typeof("failures") = 'array');
ALTER TABLE "users" ADD CONSTRAINT "ck_users_trial_questions_used" CHECK ("trial_questions_used" >= 0);

-- List filters and searches of the M02 endpoints (name, role, school). E-mail and username are already
-- covered by uq_users_email / ix_users_username_lower / uq_users_school_username (0002).
CREATE INDEX "ix_users_name_lower" ON "users" (lower("name"));
CREATE INDEX "ix_user_roles_role_user_id" ON "user_roles" ("role", "user_id");
CREATE INDEX "ix_schools_name_lower" ON "schools" (lower("name"));
CREATE INDEX "ix_schools_is_active" ON "schools" ("is_active");

-- Case-insensitive school code (BE-05 review M1): "abc" and "ABC" are the same code. The app checks first
-- (friendly 422 under an advisory lock); this index is the backstop and serves findByCode (lower(code) = ...).
CREATE UNIQUE INDEX "uq_schools_code_lower" ON "schools" (lower("code"));
